mapper.select:
SELECT kb_id, tenant_id, kb_name, description, chunk_strategy, chunk_size,
       chunk_overlap, embedding_model, status, create_time
FROM kb_knowledge_base WHERE kb_id = #{kbId}

mapper.update:
UPDATE kb_knowledge_base
SET chunk_strategy = #{chunkStrategy},
    chunk_size = #{chunkSize},
    chunk_overlap = #{chunkOverlap},
    embedding_model = #{embeddingModel}
WHERE kb_id = #{kbId}
